std::pair<
  common::optional<
    std::shared_ptr<types::ILangString>
  >,
  common::optional<DeserializationError>
> ParsePropertiesOfLangString(
  const nlohmann::json& json,
  bool additional_properties
) {
  common::optional<std::wstring> the_language;

  common::optional<std::wstring> the_text;

  common::optional<DeserializationError> error(
    ParseProperties(
      json,
      properties::kMapOfLangString,
      additional_properties,
      [&](
        properties::OfLangString property,
        const nlohmann::json& value
      ) -> common::optional<DeserializationError> {
        switch (property) {
          case properties::OfLangString::kLanguage:
            return ParseInto(
              the_language,
              DeserializeWstring(value)
            );
          case properties::OfLangString::kText:
            return ParseInto(
              the_text,
              DeserializeWstring(value)
            );
          default:
            throw UnexpectedPropertyLiteralError(
              "properties::OfLangString",
              property
            );
        }
      }
    )
  );

  if (error.has_value()) {
    return NoInstanceAndDeserializationError<
      std::shared_ptr<types::ILangString>
    >(
      std::move(*error)
    );
  }

  if (!the_language.has_value()) {
    return NoInstanceAndDeserializationErrorWithCause<
      std::shared_ptr<types::ILangString>
    >(
      L"The required property language is missing"
    );
  }

  if (!the_text.has_value()) {
    return NoInstanceAndDeserializationErrorWithCause<
      std::shared_ptr<types::ILangString>
    >(
      L"The required property text is missing"
    );
  }

  return std::make_pair(
    common::make_optional<
      std::shared_ptr<types::ILangString>
    >(
      // NOTE (mristin):
      // We deliberately do not use std::make_shared here to avoid an unnecessary
      // upcast.
      new types::LangString(
        std::move(*the_language),
        std::move(*the_text)
      )
    ),
    common::nullopt
  );
}

